package gg.grounds.player.settings

import net.kyori.adventure.key.Key

/**
 * The fonts a dialog-body menu is drawn with. They ship in the grounds-global PackSet
 * (`assets/grounds/font/menu/`), generated by the test-side `MenuPack`.
 *
 * A dialog body is plain text: lines 9 px apart, each centred, left to right. Three fonts turn that
 * into a canvas:
 * - [SPACE]: invisible glyphs of advance ±1, ±2, ±4 … ±256. [move] strings them together to put the
 *   cursor anywhere on the current line.
 * - [text]: vanilla's default font with its ascent lowered by 0..8 px, so a label can sit at any
 *   pixel height inside its line. A `reference` provider cannot change ascent, so the pack copies
 *   vanilla's provider grids; they still point at vanilla's own textures.
 * - [ART]: the menu's bitmaps, one glyph per sprite per 0..8 px drop (see [MenuArt]).
 */
internal object MenuFonts {
    const val LINE_HEIGHT = 9

    val SPACE: Key = Key.key("grounds", "menu/space")
    val ART: Key = Key.key("grounds", "menu/art")

    /**
     * Vanilla's ASCII glyphs at twice the size (a bitmap provider with `height` 16 over the 8 px
     * cells), for headings. Sits on a line's top and reaches 16 px down.
     */
    val TITLE: Key = Key.key("grounds", "menu/title")

    fun text(dy: Int): Key {
        require(dy in 0 until LINE_HEIGHT) { "dy $dy outside a line" }
        return Key.key("grounds", "menu/text_$dy")
    }

    private const val POWERS = 9 // 1 .. 256

    internal fun negChar(bit: Int) = (0xF800 + bit).toChar()

    internal fun posChar(bit: Int) = (0xF820 + bit).toChar()

    internal val powers = 0 until POWERS

    /** Glyphs in [SPACE] that move the cursor by exactly [px] (may be negative). */
    fun move(px: Int): String {
        require(px in -((1 shl POWERS) - 1)..((1 shl POWERS) - 1)) { "move $px out of range" }
        val sb = StringBuilder()
        val abs = Math.abs(px)
        for (bit in powers) {
            if (abs and (1 shl bit) != 0) sb.append(if (px < 0) negChar(bit) else posChar(bit))
        }
        return sb.toString()
    }

    /** Codepoints a label may use: Basic Latin, Latin-1 and Latin Extended-A. */
    val LABEL_RANGE = 0x20..0x17F

    /**
     * Glyph advances of vanilla's default font over [LABEL_RANGE], measured from the 26.3 client
     * jar by `MenuPack` and checked in, so the server never needs the jar.
     */
    private val advances: Map<Int, Int> by lazy { table("advances.txt") }

    private val titleAdvances: Map<Int, Int> by lazy { table("title-advances.txt") }

    private fun table(name: String): Map<Int, Int> {
        val stream =
            MenuFonts::class.java.getResourceAsStream(name)
                ?: error("$name missing next to MenuFonts")
        return stream.bufferedReader().useLines { lines ->
            lines
                .filter { it.isNotBlank() && !it.startsWith("#") }
                .associate { line ->
                    val (cp, advance) = line.split(' ')
                    cp.toInt(16) to advance.toInt()
                }
        }
    }

    /**
     * Advance of [s] in vanilla's default font (glyph width + 1 px spacing). Throws for a character
     * outside the table: it would render as a missing-glyph box and silently break the width of the
     * whole line.
     */
    fun textWidth(s: String): Int =
        s.codePoints()
            .map { cp ->
                advances[cp]
                    ?: throw IllegalArgumentException(
                        "no menu glyph for U+%04X in \"%s\"".format(cp, s)
                    )
            }
            .sum()

    /** Advance of [s] in [TITLE]. ASCII only; anything else throws, like [textWidth]. */
    fun titleWidth(s: String): Int =
        s.codePoints()
            .map { cp ->
                titleAdvances[cp]
                    ?: throw IllegalArgumentException(
                        "no title glyph for U+%04X in \"%s\"".format(cp, s)
                    )
            }
            .sum()
}
